ALTER TABLE public.tournaments ADD COLUMN revision bigint NOT NULL DEFAULT 0;
CREATE FUNCTION public.register_tournament_player(_tournament_id uuid,_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM 1 FROM public.tournaments WHERE id=_tournament_id FOR UPDATE; IF NOT public.tournament_accepts_registration(_tournament_id) THEN RAISE EXCEPTION 'TOURNAMENT_STARTED'; END IF; IF EXISTS(SELECT 1 FROM public.registrations WHERE tournament_id=_tournament_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'ALREADY_REGISTERED'; END IF; INSERT INTO public.tournament_teams(tournament_id,name,captain_id) VALUES(_tournament_id,left(coalesce(nullif(trim(_name),''),(SELECT display_name FROM public.profiles WHERE id=auth.uid()),'Joueur'),60),auth.uid()); INSERT INTO public.registrations(tournament_id,user_id) VALUES(_tournament_id,auth.uid()); INSERT INTO public.notifications(recipient_id,organization_id,kind,payload) SELECT auth.uid(),organization_id,'registration.confirmed',jsonb_build_object('tournament_id',id,'title',title) FROM public.tournaments WHERE id=_tournament_id; UPDATE public.tournaments SET revision=revision+1 WHERE id=_tournament_id; END $$;
REVOKE ALL ON FUNCTION public.register_tournament_player(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.register_tournament_player(uuid,text) TO authenticated;
CREATE FUNCTION public.cancel_tournament_registration(_tournament_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM 1 FROM public.tournaments WHERE id=_tournament_id FOR UPDATE; IF NOT public.tournament_accepts_registration(_tournament_id) THEN RAISE EXCEPTION 'TOURNAMENT_STARTED'; END IF; DELETE FROM public.tournament_teams WHERE tournament_id=_tournament_id AND captain_id=auth.uid(); DELETE FROM public.registrations WHERE tournament_id=_tournament_id AND user_id=auth.uid(); UPDATE public.tournaments SET revision=revision+1 WHERE id=_tournament_id; END $$;
REVOKE ALL ON FUNCTION public.cancel_tournament_registration(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cancel_tournament_registration(uuid) TO authenticated;
CREATE FUNCTION public.actor_manages_tournament(_actor uuid,_tournament_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tournaments t JOIN public.organizations o ON o.id=t.organization_id WHERE t.id=_tournament_id AND o.status='active' AND (EXISTS(SELECT 1 FROM public.platform_roles WHERE user_id=_actor) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=o.id AND m.user_id=_actor AND (m.role IN ('ORGANIZATION_OWNER','ORGANIZATION_ADMIN') OR (m.role='TOURNAMENT_MANAGER' AND EXISTS(SELECT 1 FROM public.tournament_manager_assignments a WHERE a.tournament_id=t.id AND a.user_id=_actor)))))) $$;
REVOKE ALL ON FUNCTION public.actor_manages_tournament(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.actor_manages_tournament(uuid,uuid) TO service_role;
CREATE FUNCTION public.commit_tournament_start(_actor uuid,_tournament_id uuid,_revision bigint,_team_ids jsonb,_matches jsonb,_code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tournaments; actual jsonb; BEGIN SELECT * INTO t FROM public.tournaments WHERE id=_tournament_id FOR UPDATE; IF NOT public.actor_manages_tournament(_actor,_tournament_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF t.status<>'open' OR t.revision<>_revision THEN RAISE EXCEPTION 'STALE_TOURNAMENT'; END IF; SELECT jsonb_agg(id ORDER BY id) INTO actual FROM public.tournament_teams WHERE tournament_id=_tournament_id; IF actual IS DISTINCT FROM (SELECT jsonb_agg(value ORDER BY value) FROM jsonb_array_elements_text(_team_ids)) THEN RAISE EXCEPTION 'STALE_ROSTER'; END IF; IF jsonb_array_length(actual)<2 OR (t.max_participants IS NOT NULL AND jsonb_array_length(actual)<t.max_participants) THEN RAISE EXCEPTION 'Tournament not full'; END IF; IF length(_code)<4 OR jsonb_array_length(_matches)<1 THEN RAISE EXCEPTION 'Invalid start'; END IF; INSERT INTO public.tournament_matches(tournament_id,stage,pool_index,round,position,team_a,team_b,winner) SELECT _tournament_id,x.stage,x.pool_index,x.round,x.position,x.team_a,x.team_b,x.winner FROM jsonb_to_recordset(_matches) AS x(stage text,pool_index integer,round integer,position integer,team_a uuid,team_b uuid,winner uuid); INSERT INTO public.tournament_settings_codes(tournament_id,code) VALUES(_tournament_id,_code) ON CONFLICT(tournament_id) DO UPDATE SET code=excluded.code,updated_at=now(); UPDATE public.tournaments SET status='started',revision=revision+1 WHERE id=_tournament_id; INSERT INTO public.organization_audit_events(organization_id,actor_id,action) VALUES(t.organization_id,_actor,'tournament.started'); END $$;
REVOKE ALL ON FUNCTION public.commit_tournament_start(uuid,uuid,bigint,jsonb,jsonb,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.commit_tournament_start(uuid,uuid,bigint,jsonb,jsonb,text) TO service_role;
CREATE UNIQUE INDEX tournament_match_unique_slot ON public.tournament_matches(tournament_id,stage,coalesce(pool_index,-1),round,position);
ALTER TABLE public.tournament_matches ADD CONSTRAINT match_different_opponents CHECK(team_a IS NULL OR team_b IS NULL OR team_a<>team_b) NOT VALID;
ALTER TABLE public.tournament_matches ADD CONSTRAINT match_winner_is_opponent CHECK(winner IS NULL OR winner=team_a OR winner=team_b) NOT VALID;
CREATE FUNCTION public.guard_team_roster() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; current_status text; BEGIN target:=CASE WHEN TG_OP='DELETE' THEN OLD.tournament_id ELSE NEW.tournament_id END; SELECT status INTO current_status FROM public.tournaments WHERE id=target FOR UPDATE; IF TG_OP='UPDATE' AND NEW.tournament_id IS DISTINCT FROM OLD.tournament_id THEN RAISE EXCEPTION 'Tournament reassignment forbidden'; END IF; IF TG_OP='DELETE' AND current_status IS NOT NULL AND current_status<>'open' THEN RAISE EXCEPTION 'Started tournament roster is protected'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_team_roster() FROM PUBLIC; CREATE TRIGGER tournament_teams_roster_guard BEFORE UPDATE OR DELETE ON public.tournament_teams FOR EACH ROW EXECUTE FUNCTION public.guard_team_roster();